import { describe, expect, it } from 'vitest'
import { err, ok } from '#core/kernel/result'
import { remoteFailed } from '../../shared/domain/catalog/errors'
import { products } from '../../shared/application/catalog/queries/products'
import { fakeCatalogRepository } from './fake-repository'

describe('products', () => {
  it('returns what the API answers', async () => {
    const repository = fakeCatalogRepository({ products: async () => ok([
      {
        id: 1,
        name: 'name 1',
        price: 1.5,
        inStock: true,
        createdAt: '2024-01-02T03:04:05.000Z',
        note: 'note 1',
        categories: [
          {
            id: 1,
            name: 'name 1'
          }
        ]
      }
    ]) })
    const result = await products({ catalog: repository })({
      category: 'category 1',
      locale: 'locale 1'
    })
    expect(result).toEqual({ ok: true, value: [
      {
        id: 1,
        name: 'name 1',
        price: 1.5,
        inStock: true,
        createdAt: '2024-01-02T03:04:05.000Z',
        note: 'note 1',
        categories: [
          {
            id: 1,
            name: 'name 1'
          }
        ]
      }
    ] })
  })

  it('returns a failure of the API as a remote_failed error', async () => {
    const repository = fakeCatalogRepository({ products: async () => err(remoteFailed(503, 'answered 503')) })
    const result = await products({ catalog: repository })({
      category: 'category 1',
      locale: 'locale 1'
    })
    expect(result).toEqual({ ok: false, error: expect.objectContaining({ type: 'remote_failed', status: 503 }) })
  })

  it('refuses an input that is not valid, without calling the API', async () => {
    const repository = fakeCatalogRepository()
    const result = await products({ catalog: repository })({ category: 42 } as never)
    expect(result).toEqual({ ok: false, error: expect.objectContaining({ type: 'invalid_input' }) })
  })
})
